function AdminUsers() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    try {
      const res = await fetch(`${API}/users`);
      const data = await res.json();
      setUsers(data.users || []);
    } catch (err) {
      setError('Failed to fetch users');
    } finally {
      setLoading(false);
    }
  };

  const filteredUsers = users
    .filter(user => 
      user.FullName?.toLowerCase().includes(search.toLowerCase()) ||
      user.Email?.toLowerCase().includes(search.toLowerCase()) ||
      user.UserID?.toString().includes(search)
    )
    .sort((a, b) => a.UserID - b.UserID); // Sort by ascending User ID

  if (loading) {
    return (
      <div>
        <div className="page-header">
          <div>
            <div className="page-title">USER MANAGEMENT</div>
            <div className="page-sub">Manage user accounts</div>
          </div>
        </div>
        <div className="loading"><div className="spinner" /> Loading users...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div>
        <div className="page-header">
          <div>
            <div className="page-title">USER MANAGEMENT</div>
            <div className="page-sub">Manage user accounts</div>
          </div>
        </div>
        <div className="alert alert-error">{error}</div>
      </div>
    );
  }

  return (
    <div>
      <div className="page-header">
        <div>
          <div className="page-title">USER MANAGEMENT</div>
          <div className="page-sub">{filteredUsers.length} of {users.length} users</div>
        </div>
        <button className="btn btn-cyan" onClick={fetchUsers}>
          🔄 Refresh
        </button>
      </div>

      <div className="search-bar">
        <div className="search-wrap">
          <span className="search-icon">🔍</span>
          <input 
            className="search-input" 
            placeholder="Search users by name, email, or ID..." 
            value={search}
            onChange={e => setSearch(e.target.value)} 
          />
        </div>
        {search && <button className="btn btn-ghost btn-sm" onClick={() => setSearch('')}>Clear</button>}
      </div>

      {filteredUsers.length === 0 ? (
        <div className="empty">
          <div className="empty-icon">👥</div>
          <p>{search ? 'No users match your search' : 'No users found'}</p>
        </div>
      ) : (
        <div style={{ 
          background: 'var(--card)', 
          borderRadius: 'var(--radius)', 
          overflow: 'hidden',
          border: '1px solid var(--border)',
          boxShadow: 'var(--cyan-glow)'
        }}>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ 
                background: 'linear-gradient(135deg, var(--cyan), var(--purple))', 
                color: 'var(--text)',
                fontFamily: 'Orbitron, monospace'
              }}>
                <th style={{ padding: '16px', textAlign: 'left', fontWeight: '600', fontSize: '14px', letterSpacing: '1px' }}>USER ID</th>
                <th style={{ padding: '16px', textAlign: 'left', fontWeight: '600', fontSize: '14px', letterSpacing: '1px' }}>NAME</th>
                <th style={{ padding: '16px', textAlign: 'left', fontWeight: '600', fontSize: '14px', letterSpacing: '1px' }}>EMAIL</th>
                <th style={{ padding: '16px', textAlign: 'left', fontWeight: '600', fontSize: '14px', letterSpacing: '1px' }}>PHONE</th>
                <th style={{ padding: '16px', textAlign: 'left', fontWeight: '600', fontSize: '14px', letterSpacing: '1px' }}>STATUS</th>
              </tr>
            </thead>
            <tbody>
              {filteredUsers.map((user, index) => (
                <tr key={user.UserID} style={{ 
                  borderBottom: '1px solid var(--border2)',
                  background: index % 2 === 0 ? 'var(--card2)' : 'var(--card)',
                  transition: 'all 0.3s',
                  fontFamily: 'Rajdhani, sans-serif'
                }}>
                  <td style={{ padding: '16px', fontSize: '15px', fontWeight: '600', color: 'var(--cyan)' }}>#{user.UserID}</td>
                  <td style={{ padding: '16px', fontSize: '15px', color: 'var(--text)' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                      <div style={{ 
                        width: '32px', 
                        height: '32px', 
                        borderRadius: '50%',
                        background: 'linear-gradient(135deg, var(--cyan), var(--purple))',
                        color: 'var(--bg)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        fontSize: '14px',
                        fontWeight: '700',
                        fontFamily: 'Orbitron, monospace',
                        boxShadow: 'var(--cyan-glow)'
                      }}>
                        {user.FullName?.[0]?.toUpperCase() || 'U'}
                      </div>
                      <span style={{ fontWeight: '600' }}>{user.FullName}</span>
                    </div>
                  </td>
                  <td style={{ padding: '16px', fontSize: '15px', color: 'var(--text2)' }}>{user.Email}</td>
                  <td style={{ padding: '16px', fontSize: '15px', color: 'var(--text2)' }}>{user.Phone || '—'}</td>
                  <td style={{ padding: '16px' }}>
                    <span style={{ 
                      padding: '6px 14px',
                      borderRadius: '20px',
                      fontSize: '12px',
                      fontWeight: '700',
                      fontFamily: 'Orbitron, monospace',
                      letterSpacing: '1px',
                      background: user.AccountStatus === 'Active' ? 'var(--green-dim)' : 'var(--orange-dim)',
                      color: user.AccountStatus === 'Active' ? 'var(--green)' : 'var(--orange)',
                      border: user.AccountStatus === 'Active' ? '1px solid var(--green)' : '1px solid var(--orange)',
                      boxShadow: user.AccountStatus === 'Active' ? '0 0 10px rgba(0,255,136,0.3)' : '0 0 10px rgba(255,107,0,0.3)'
                    }}>
                      {user.AccountStatus}
                    </span>
                  </td>
                  <td style={{ padding: '16px' }}>
                    <button 
                      className="btn btn-cyan btn-sm"
                      style={{ 
                        padding: '8px 16px',
                        fontSize: '12px',
                        fontFamily: 'Orbitron, monospace',
                        letterSpacing: '1px',
                        fontWeight: '600'
                      }}
                    >
                      VIEW
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

